-- =====================================================
-- Coach today-only write restriction
--
-- Replaces the two broad "for all" coach policies with
-- fine-grained per-command policies:
--
--   attendance_sessions (coach):
--     SELECT  → any session for their group (all history)
--     UPDATE  → only today's sessions (mark complete/cancel)
--     INSERT  → denied (sessions are generated by cron)
--     DELETE  → denied
--
--   attendance_records (coach):
--     SELECT  → any record for their group's sessions (all history)
--     INSERT  → only into today's sessions
--     UPDATE  → only records belonging to today's sessions
--     DELETE  → denied
-- =====================================================

-- 1. Drop the existing broad coach policies
drop policy if exists "sessions_coach_own" on attendance_sessions;
drop policy if exists "records_coach_own"  on attendance_records;

-- 2. attendance_sessions — split coach policies

-- SELECT: full history for the coach's groups
create policy "sessions_coach_select" on attendance_sessions
  for select to authenticated using (
    app_current_role() = 'coach'
    and school_id = current_school_id()
    and is_coach_for_group(group_id)
  );

-- UPDATE: only today's sessions (tamamla veya iptal et)
create policy "sessions_coach_update_today" on attendance_sessions
  for update to authenticated
  using (
    app_current_role() = 'coach'
    and school_id = current_school_id()
    and is_coach_for_group(group_id)
    and session_date = current_date
  )
  with check (
    app_current_role() = 'coach'
    and school_id = current_school_id()
    and is_coach_for_group(group_id)
    and session_date = current_date
  );

-- 3. attendance_records — split coach policies

-- SELECT: full history for records belonging to the coach's groups
create policy "records_coach_select" on attendance_records
  for select to authenticated using (
    app_current_role() = 'coach'
    and exists (
      select 1 from attendance_sessions s
      where s.id = attendance_records.session_id
        and is_coach_for_group(s.group_id)
    )
  );

-- INSERT: only into today's sessions
create policy "records_coach_insert_today" on attendance_records
  for insert to authenticated
  with check (
    app_current_role() = 'coach'
    and exists (
      select 1 from attendance_sessions s
      where s.id = attendance_records.session_id
        and is_coach_for_group(s.group_id)
        and s.session_date = current_date
    )
  );

-- UPDATE: only records whose session is today
create policy "records_coach_update_today" on attendance_records
  for update to authenticated
  using (
    app_current_role() = 'coach'
    and exists (
      select 1 from attendance_sessions s
      where s.id = attendance_records.session_id
        and is_coach_for_group(s.group_id)
        and s.session_date = current_date
    )
  )
  with check (
    app_current_role() = 'coach'
    and exists (
      select 1 from attendance_sessions s
      where s.id = attendance_records.session_id
        and is_coach_for_group(s.group_id)
        and s.session_date = current_date
    )
  );
